import { Guard } from "./guards.js";
function ObjectEnumValues(type) {
  const keys = Guard.Keys(type).filter((key) => isNaN(key));
  return keys.map((key) => type[key]);
}
export function Enum(value) {
  const values = Guard.IsObjectNotArray(value) ? ObjectEnumValues(value) : value;
  return { kind: "Enum", enum: values };
}
export function Named(value, name) {
  return value[name];
}
